    - ed_lin ltac:(cbn [ev ENV]; rewrite ?P0, ?P141). unorm. lia.
    - ed_lin ltac:(cbn [ev ENV]; rewrite ?P0, ?P141). unorm. lia.
    - cbn [edenot length]. reflexivity.
    - cbn [length Z.of_nat]. lia.
