  Lemma seg_H4 : ltac2:(zQ "i10!j7!q0!ik2!jja!nnb!ku8!ihf!ir0!ip7!h8!ipf!q5!ir6!ns0!nv7!og0!oie!oj7!qqd!uv1!uva!oq7!or3!orb!ovd!pk9!qsc!pl5!qt6!plf!pu9!pv4!hif>4vals@1$9@1$1@1$0#k0>1R@2$h0@1$0#5@1$1@1$0#k0>1M>0@1$1@1$0#k0@1$c@1$1@1$0#8>3msF$4>2mo$e>0@3$2$a@2$8@1$1@1$0#k0^5Nhg3>0@3$2@1$1@1$0#k0@2$i0^6N0?3sp0>0@3$hf@1$5^7$h4^6>0@4$he$3@1$5^8^6$h3>0@3$h1^6^5^7>0@3$2$4@3$h5?1L?1S^7@5$h6?2fx^9@2$6@1$0#k0$h2^8@1$h7$3@4$h9$3$h8@2$d^8^7@2$ha@2$hc+2@3$7@1$1@1$0#8@2$6@1$0#8+a@1$b@1$1@1$0#8@2$hb@1$hd+2@1$f?3mo0").
